import{_ as i,o as t,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const D=JSON.parse('{"title":"CDS G/H (Day 1) - RBD review","description":"","frontmatter":{"title":"CDS G/H (Day 1) - RBD review","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["Ceph","RBD","分布式存储","性能优化","多站点复制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_RBD_review.md","filePath":"posts/2014/CDS_G_H_Day_1_-_RBD_review.md","lastUpdated":1780459816000}'),o={name:"posts/2014/CDS_G_H_Day_1_-_RBD_review.md"};function e(n,l,a,_,g,u){return t(),r("div",null,[...l[0]||(l[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： RBD（Rados Block Device）功能回顾与讨论</p><p><strong>会议时间</strong>： 2023年10月27日</p><p><strong>参会人员</strong>： Sage, Josh, Sarah, Adam, Greg 等</p><p><strong>会议内容</strong>：</p><p><strong>1. RBD 日志记录与镜像功能讨论</strong></p><ul><li><strong>日志记录</strong>： <ul><li>RBD 日志记录功能旨在实现异步复制，支持跨数据中心或集群的数据复制。</li><li>日志记录会将所有数据操作写入日志文件，并通过 Raft 对象进行条带化存储。</li><li>读取日志文件并重新播放到其他集群或池，实现数据的异步复制。</li><li>需要解决的问题包括日志文件的存储位置、镜像代理的结构和同步机制等。</li></ul></li><li><strong>镜像代理</strong>： <ul><li>需要设计一个能够协调多个代理之间工作负载的镜像代理。</li><li>可以考虑使用一个调度过程来管理需要镜像的图像列表，并为每个图像运行子进程进行镜像。</li><li>镜像代理可以在目标集群中运行，以避免网络接口成为瓶颈。</li></ul></li></ul><p><strong>2. RBD 功能讨论</strong></p><ul><li><strong>多站点复制</strong>： <ul><li>目前可以使用 RBD 快照和快照镜像实现多站点复制，但实时性较差。</li><li>新的异步复制功能可以实现更近实时的多站点复制。</li></ul></li><li><strong>默认缓存</strong>： <ul><li>可以考虑将缓存设置为默认选项，以提高性能。</li><li>需要确定合适的默认缓存策略。</li></ul></li><li><strong>对象缓存</strong>： <ul><li>修复了对象缓存中的一些性能问题。</li><li>可以考虑改进对象缓存的性能。</li></ul></li><li><strong>RBD df 命令</strong>： <ul><li>可以使用 RBD df 命令查看已分配的空间和实际使用空间。</li></ul></li><li><strong>iSCSI 集成</strong>： <ul><li>目前 iSCSI 集成功能有限，需要改进。</li><li>需要提供更完善的文档和工具。</li></ul></li><li><strong>用户空间 passthrough</strong>： <ul><li>可以考虑使用用户空间 passthrough 来利用 RBD 的新特性。</li></ul></li><li><strong>性能监控</strong>： <ul><li>可以改进性能监控功能，以更好地监控 RBD 集群的性能。</li></ul></li><li><strong>客户端识别</strong>： <ul><li>可以改进客户端识别功能，以便更好地跟踪不同客户端的 I/O 模式。</li></ul></li></ul><p><strong>3. RBD 丢弃功能</strong></p><ul><li>RBD 丢弃功能已接近完成，但仍有一些问题需要解决。</li><li>将进行更多的测试，以确保该功能的可靠性。</li></ul><p><strong>4. 其他事项</strong></p><ul><li>将讨论 RBD 的格式化、条带化等功能。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Josh 将负责 RBD 日志记录和镜像功能的设计和实现。</li><li>其他开发人员将负责 RBD 其他功能的改进和优化。</li><li>将继续进行 RBD 丢弃功能的测试和修复。</li><li>将讨论 RBD 的格式化、条带化等功能。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph 领域的英文关键词，如 Raft、Raft 对象、条带化、异步复制、多站点复制、快照、缓存、性能监控、客户端识别等。</li></ul>',17)])])}const R=i(o,[["render",e]]);export{D as __pageData,R as default};
